#[put("/collections/{collection_name}/points")]
async fn upsert_points(
    dispatcher: web::Data<Dispatcher>,
    collection: Path<CollectionPath>,
    operation: Json<PointInsertOperations>,
    params: Query<UpdateParams>,
    // ...
) -> impl Responder {
    let request_hw_counter = get_request_hardware_counter(
        &dispatcher,
        collection.collection_name.clone(),
        service_config.hardware_reporting(),
        Some(params.wait),  // wait parameter affects validation timing
    );

    let result_with_usage = do_upsert_points(
        StrictModeCheckedTocProvider::new(&dispatcher),
        collection.into_inner().collection_name,
        operation,
        InternalUpdateParams::default(),
        params.into_inner(),  // contains wait parameter
        auth,
        inference_params,
        request_hw_counter.get_counter(),
    ).await;
